package cl.bolsillo.app;

import android.graphics.Color;
import android.text.Editable;
import android.text.TextWatcher;
import android.view.Gravity;
import android.view.View;
import android.widget.*;
import org.json.*;
import java.util.*;

/** One tap chooses an existing category; additional records require explicit scope. */
final class QuickCategory {
 static boolean needsCategory(JSONObject data,JSONObject tx){return CategoryEdits.needsCategory(data,tx);}
 static void show(MainActivity a,String txId){a.attempt(()->{Session session=create(a,txId);session.dialog.show();});}
 static Session create(MainActivity a,String txId)throws Exception{return new Session(a,txId);}
 static List<JSONObject> ranked(JSONObject data,String type)throws Exception{return ranked(data,type,null);}
 /** Context changes ordering only. It never selects, creates or teaches a category. */
 static List<JSONObject> ranked(JSONObject data,String type,JSONObject anchor)throws Exception{
  List<JSONObject> cats=new ArrayList<>();Map<String,JSONObject> valid=new HashMap<>();Map<String,Integer> score=new HashMap<>(),context=new HashMap<>();JSONArray list=data.getJSONArray("categories"),txs=data.getJSONArray("transactions");
  for(int i=0;i<list.length();i++){JSONObject cat=list.getJSONObject(i);if(type.equals(cat.optString("type"))&&!cat.optBoolean("archived")&&!cat.optBoolean("deleted")){cats.add(cat);if(!CategoryEdits.otherCategory(cat))valid.put(cat.optString("id"),cat);}}
  String concept=anchor!=null&&type.equals(anchor.optString("type"))?ConceptCatalog.concept(anchor.optString("note")):"";boolean specific=!ConceptCatalog.generic(concept);
  for(int i=0;i<txs.length();i++){JSONObject tx=txs.getJSONObject(i);String category=tx.optString("category");if(type.equals(tx.optString("type"))&&!tx.optBoolean("archived")&&!tx.optBoolean("deleted")&&"posted".equals(tx.optString("status"))&&valid.containsKey(category)){score.put(category,score.getOrDefault(category,0)+1);if(specific&&concept.equals(ConceptCatalog.concept(tx.optString("note"))))context.put(category,context.getOrDefault(category,0)+1);}}
  JSONArray recurring=data.optJSONArray("recurring");if(specific&&recurring!=null)for(int i=0;i<recurring.length();i++){JSONObject r=recurring.optJSONObject(i);if(r!=null&&type.equals(r.optString("type"))&&r.optBoolean("active",true)&&!r.optBoolean("archived")&&!r.optBoolean("deleted")&&valid.containsKey(r.optString("category"))&&concept.equals(ConceptCatalog.concept(r.optString("name"))))context.put(r.optString("category"),context.getOrDefault(r.optString("category"),0)+2);}
  if(context.isEmpty()&&type.equals("expense")&&(concept.equals("netflix")||concept.equals("spotify")))for(JSONObject cat:cats)if(Arrays.asList("suscripcion","suscripciones").contains(ConceptCatalog.normalize(cat.optString("name")))&&valid.containsKey(cat.optString("id")))context.put(cat.optString("id"),1);
  cats.sort((x,y)->{int other=Boolean.compare(CategoryEdits.otherCategory(x),CategoryEdits.otherCategory(y));if(other!=0)return other;int preferred=Integer.compare(context.getOrDefault(y.optString("id"),0),context.getOrDefault(x.optString("id"),0));if(preferred!=0)return preferred;int count=Integer.compare(score.getOrDefault(y.optString("id"),0),score.getOrDefault(x.optString("id"),0));return count!=0?count:x.optString("name").compareToIgnoreCase(y.optString("name"));});return cats;
 }
 static final class Session {
  final MainActivity a;final SheetDialog dialog;final LinearLayout box,results,scope;final EditText search;final List<JSONObject> categories;final CategoryEdits.Plan single,multiple;final Map<String,View> choices=new LinkedHashMap<>();final View firstScope,groupScope;
  boolean batch;SheetDialog child;AutoCompleteTextView name;
  Session(MainActivity host,String id)throws Exception{
   a=host;JSONObject data=LocalData.read(a);single=CategoryEdits.plan(data,id,false);CategoryEdits.Plan together=null;try{CategoryEdits.Plan candidate=CategoryEdits.plan(data,id,true);if(candidate.count()>1)together=candidate;}catch(Exception noGroup){}multiple=together;JSONObject tx=Ledger.find(data.getJSONArray("transactions"),id);categories=ranked(data,single.type,tx);
   box=Modern.column(a);box.setPadding(a.dp(18),a.dp(17),a.dp(18),a.dp(12));LinearLayout heading=Modern.row(a);heading.addView(Modern.text(a,"Categoría",25,Glass.ink(a),false),new LinearLayout.LayoutParams(0,-2,1));heading.addView(Icons.view(a,"tag",Glass.accent(a),24),new LinearLayout.LayoutParams(a.dp(24),a.dp(24)));box.addView(heading);String merchant=ConceptCatalog.label(tx.optString("note"));if(merchant.isEmpty())merchant=single.type.equals("expense")?"Gasto":"Ingreso";TextView detail=Modern.text(a,merchant,13,Glass.subtle(a),false);detail.setMaxLines(2);Modern.add(box,detail,6);
   scope=Modern.column(a);firstScope=scopeRow("Este movimiento",1,true,()->{batch=false;paintScope();});scope.addView(firstScope);if(multiple!=null){groupScope=scopeRow("Mismo comercio",multiple.count(),false,()->{batch=true;paintScope();});groupScope.setContentDescription("Mismo comercio: "+multiple.count()+" movimientos en total, incluido este. Solo movimientos en Otros.");Modern.add(scope,groupScope,6);Modern.add(box,scope,15);}else groupScope=null;
   results=Modern.column(a);LinearLayout searchBox=Modern.row(a);searchBox.setBackground(Glass.material(a,222,17,Glass.secondary(a)));searchBox.setPadding(a.dp(12),0,a.dp(10),0);searchBox.addView(Icons.view(a,"search",Glass.subtle(a),20),new LinearLayout.LayoutParams(a.dp(20),a.dp(20)));search=new EditText(a);search.setHint("Buscar categoría");search.setContentDescription("Buscar categoría");search.setTextSize(15);search.setTypeface(Glass.font(a,400));search.setTextColor(Glass.ink(a));search.setHintTextColor(Glass.subtle(a));search.setSingleLine(true);Glass.editor(search);search.setBackgroundColor(Color.TRANSPARENT);search.setPadding(a.dp(10),a.dp(12),0,a.dp(12));search.setMinHeight(a.dp(52));searchBox.addView(search,new LinearLayout.LayoutParams(0,-2,1));Modern.add(box,searchBox,16);Modern.add(box,results,10);
   dialog=new SheetDialog(a,box);LinearLayout footer=Modern.row(a);Button cancel=Glass.button(a,"Cancelar"),create=Glass.button(a,"Nueva categoría");LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,-2,.36f);cp.rightMargin=a.dp(8);footer.addView(cancel,cp);footer.addView(create,new LinearLayout.LayoutParams(0,-2,.64f));dialog.footer.addView(footer);cancel.setOnClickListener(v->dialog.dismiss());create.setOnClickListener(v->newCategory());dialog.setOnDismissListener(d->{if(child!=null)child.dismiss();});search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){}public void afterTextChanged(Editable text){renderChoices();}});renderChoices();
  }
  View scopeRow(String label,int count,boolean selected,Runnable action){LinearLayout row=Modern.row(a);row.setPadding(a.dp(12),a.dp(10),a.dp(12),a.dp(10));TextView text=Modern.text(a,label,14,Glass.ink(a),true);text.setMaxLines(2);row.addView(text,new LinearLayout.LayoutParams(0,-2,1));TextView number=Modern.chip(a,String.valueOf(count),Glass.accent(a));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,-2);p.leftMargin=a.dp(7);row.addView(number,p);row.setMinimumHeight(a.dp(48));row.setContentDescription(label+" ("+count+(count==1?" movimiento)":" movimientos)"));row.setBackground(Glass.material(a,selected?244:210,17,selected?Glass.primary(a):Glass.secondary(a)));row.setSelected(selected);Modern.press(row,action);return row;}
  void paintScope(){firstScope.setSelected(!batch);firstScope.setBackground(Glass.material(a,batch?210:244,17,batch?Glass.secondary(a):Glass.primary(a)));if(groupScope!=null){groupScope.setSelected(batch);groupScope.setBackground(Glass.material(a,batch?244:210,17,batch?Glass.primary(a):Glass.secondary(a)));}}
  CategoryEdits.Plan selection(){return batch&&multiple!=null?multiple:single;}
  void renderChoices(){results.removeAllViews();choices.clear();String filter=ConceptCatalog.normalize(search.getText().toString());List<JSONObject> visible=new ArrayList<>();for(JSONObject cat:categories)if(filter.isEmpty()||ConceptCatalog.normalize(cat.optString("name")).contains(filter))visible.add(cat);if(filter.isEmpty()){
    TextView hint=Modern.text(a,"Sugeridas",11,Glass.subtle(a),true);results.addView(hint);int fast=0;for(JSONObject cat:visible)if(!CategoryEdits.otherCategory(cat)&&fast<5)fast++;for(int start=0;start<fast;start+=2){LinearLayout row=Modern.row(a);for(int n=0;n<2;n++){int index=start+n;if(index<fast){JSONObject cat=visible.get(index);View choice=choice(cat,true);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);if(n==0)p.rightMargin=a.dp(7);row.addView(choice,p);}else row.addView(new View(a),new LinearLayout.LayoutParams(0,1,1));}Modern.add(results,row,7);}TextView all=Modern.text(a,"Todas",11,Glass.subtle(a),true);Modern.add(results,all,16);
   }
   if(visible.isEmpty()){Modern.add(results,Modern.text(a,"Sin coincidencias",14,Glass.subtle(a),false),10);return;}for(JSONObject cat:visible)Modern.add(results,choice(cat,false),6);
  }
  View choice(JSONObject cat,boolean compact){LinearLayout row=Modern.row(a);row.setPadding(a.dp(compact?10:12),a.dp(12),a.dp(compact?10:12),a.dp(12));row.setMinimumHeight(a.dp(56));row.setBackground(Glass.material(a,222,18,Glass.secondary(a)));row.addView(Icons.view(a,Modern.iconFor(cat.optString("name")),Glass.accent(a),22),new LinearLayout.LayoutParams(a.dp(22),a.dp(22)));TextView label=Modern.text(a,cat.optString("name"),compact?12:15,Glass.ink(a),true);label.setMaxLines(compact?3:2);label.setPadding(a.dp(9),0,0,0);row.addView(label,new LinearLayout.LayoutParams(0,-2,1));row.setContentDescription("Elegir categoría: "+cat.optString("name"));Modern.press(row,()->apply(cat.optString("id")));if(!compact)choices.put(cat.optString("id"),row);return row;}
  void apply(String id){a.attempt(()->{CategoryEdits.Result result=CategoryEdits.apply(a,selection(),id);dialog.dismiss();a.render(false);NativeSettings.info(a,result.count()>1?result.count()+" movimientos clasificados":result.count()==1?"Categoría guardada":"Ya tiene esa categoría");});}
  void newCategory(){LinearLayout panel=Modern.column(a);panel.setPadding(a.dp(18),a.dp(17),a.dp(18),a.dp(14));panel.addView(Modern.text(a,"Nueva categoría",24,Glass.ink(a),false));List<String> suggestions=new ArrayList<>();try{JSONArray cats=LocalData.read(a).getJSONArray("categories");for(int i=0;i<cats.length();i++){JSONObject cat=cats.getJSONObject(i);if(single.type.equals(cat.optString("type")))suggestions.add(cat.optString("name"));}}catch(Exception ignored){}name=NativeSettings.conceptInput(a,panel,"Nombre",search.getText().toString().trim(),suggestions);SheetDialog sheet=new SheetDialog(a,panel);sheet.actions("Crear y aplicar",()->a.attempt(()->{CategoryEdits.Result result=CategoryEdits.createAndApply(a,selection(),name.getText().toString().trim());sheet.dismiss();dialog.dismiss();a.render(false);NativeSettings.info(a,result.count()>1?result.count()+" movimientos clasificados":"Categoría guardada");}));if(child!=null)child.dismiss();child=sheet;sheet.setOnDismissListener(d->{if(child==sheet)child=null;});sheet.show();}
 }
}
